SELECT product_id, CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 50 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(quantity * unit_price) AS revenue, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM order_items GROUP BY product_id, CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 50 THEN 'mid' ELSE 'low' END HAVING SUM(quantity * unit_price) < 53 ORDER BY product_id ASC
